package nl.slimov.app;
import android.content.Context;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.GZIPInputStream;import org.json.*;
public final class MonitorNetwork {
 private static final Map<String,String> tags=new HashMap<>();private static final Map<String,byte[]> cache=new HashMap<>();private static final Map<String,Long> times=new HashMap<>();
 public static synchronized byte[] get(String url,int limit,long ttl,String nsKey)throws Exception{long now=System.currentTimeMillis();if(cache.containsKey(url)&&now-times.getOrDefault(url,0L)<ttl)return cache.get(url);HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","SlimOV/0.4.0 (https://github.com/lewis091dc/slimOV)");c.setRequestProperty("Accept-Encoding","gzip");if(nsKey!=null&&!nsKey.isEmpty())c.setRequestProperty("Ocp-Apim-Subscription-Key",nsKey);if(tags.containsKey(url))c.setRequestProperty("If-None-Match",tags.get(url));try{int status=c.getResponseCode();if(status==304&&cache.containsKey(url)){times.put(url,now);return cache.get(url);}if(status!=200)throw new IOException(status==401||status==403?"NS-sleutel ontbreekt of heeft geen toegang tot dit API-product":status==429?"Bronlimiet bereikt; probeer later opnieuw":"Bron niet bereikbaar (HTTP "+status+")");InputStream input=c.getInputStream();if("gzip".equalsIgnoreCase(c.getContentEncoding()))input=new GZIPInputStream(input);byte[] body=LiveStream.readBounded(input,limit);if(cache.size()>20){cache.clear();times.clear();tags.clear();}cache.put(url,body);times.put(url,now);String tag=c.getHeaderField("ETag");if(tag!=null)tags.put(url,tag);return body;}finally{c.disconnect();}}
 public static JSONObject trip(String id)throws Exception{return new JSONObject(new String(get("https://api.transitous.org/api/v6/trip?tripId="+URLEncoder.encode(id,"UTF-8")+"&detailedLegs=false&joinInterlinedLegs=false&withScheduledSkippedStops=true&language=nl",4*1024*1024,45000,null),StandardCharsets.UTF_8));}
 public static JSONObject vehicles()throws Exception{return Proto.vehicles(get("https://gtfs.ovapi.nl/nl/vehiclePositions.pb",10*1024*1024,15000,null));}
 public static JSONObject alerts()throws Exception{return Proto.alerts(get("https://gtfs.ovapi.nl/nl/alerts.pb",20*1024*1024,60000,null));}
 public static synchronized void invalidateNs(){for(String url:new ArrayList<>(cache.keySet()))if(url.startsWith("https://gateway.apiportal.ns.nl/")){cache.remove(url);times.remove(url);tags.remove(url);}}
 public static Object ns(Context c,String path)throws Exception{String key=SecretStore.get(c);if(key.isEmpty())throw new Exception("Stel eerst je NS API-sleutel in bij Instellingen");String text=new String(get("https://gateway.apiportal.ns.nl/virtual-train-api"+path,8*1024*1024,30000,key),StandardCharsets.UTF_8);return text.trim().startsWith("[")?new JSONArray(text):new JSONObject(text);}
}
